            tls_pointer_zero_found |= string_starts_with_sequence(symbol->name, S8(".L.static_zero_aggregate_sum.tls_pointer_zero.")) &&
                                      symbol->section == OBJECT_SECTION_THREAD_LOCAL_ZERO;
