                BUSTER_TEST(arguments, fixture_spawn.handle != 0);
                if (fixture_spawn.handle)
                {
                    BUSTER_TEST(arguments, os_process_wait_sync(c23_temporary.arena, fixture_spawn).result == PROCESS_RESULT_SUCCESS);
                }
